 TextView statusCard(LinearLayout parent,String title,String value,int accent){LinearLayout c=vertical();c.setPadding(dp(12),dp(11),dp(12),dp(11));c.setBackground(border(CARD,15));TextView t=text(title,9,accent,true);c.addView(t);gap(c,5);TextView v=text(value,13,TEXT,true);c.addView(v);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));parent.addView(c,lp);return v;}
