 Button miniButton(String title,View.OnClickListener listener){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(11);b.setTextColor(TEXT);b.setBackground(border(CARD,11));b.setOnClickListener(listener);return b;}
 String prettyConnection(String s){if("CONECTADA".equals(s))return "Conectada";if("OCUPADA".equals(s))return "Ocupada";return s==null?"Desconectada":s;}
 String shortCamera(String name){if(name==null||name.isEmpty())return "Canon";return name.length()>12?name.substring(0,12):name;}
 void updateBackfillBanner(CaptureService s){if(backfillBanner==null)return;if(s==null){backfillBanner.setVisibility(View.GONE);return;}if(s.backfillWaiting){backfillBanner.setVisibility(View.VISIBLE);backfillBannerText.setText("Encontramos "+s.backfillFound+" foto(s) novas na câmera. Elas ainda não foram baixadas.");backfillDownload.setVisibility(View.VISIBLE);backfillIgnore.setVisibility(View.VISIBLE);}else if(s.backfillRunning){backfillBanner.setVisibility(View.VISIBLE);backfillBannerText.setText("Recuperando retroativas · "+s.backfillDone+" / "+s.backfillFound+" · as próximas serão editadas e passarão pela curadoria.");backfillDownload.setVisibility(View.GONE);backfillIgnore.setVisibility(View.GONE);}else backfillBanner.setVisibility(View.GONE);}

