 void updateFilterButtons(){String[] values={"all","approved","review","sent","pending"};for(int i=0;i<galleryFilterButtons.length;i++)if(galleryFilterButtons[i]!=null){boolean on=values[i].equals(galleryFilter);galleryFilterButtons[i].setTextColor(on?Color.WHITE:TEXT);galleryFilterButtons[i].setBackground(shape(on?BLUE:CARD,12));}}
 void refreshGalleryQueue(boolean force){if(galleryQueue==null)return;String gid=getSharedPreferences("hisho",0).getString("fottoGalleryId","");int reviews=database.reviewCount();double avg=database.averageScore();galleryTaskLabel.setText(reviews>0?reviews+" para revisar"+(avg>0?" · média técnica "+String.format(Locale.getDefault(),"%.1f/10",avg):""):"Tudo revisado"+(avg>0?" · média técnica "+String.format(Locale.getDefault(),"%.1f/10",avg):""));int[] gst=database.fottoStats(gid);String sig=galleryFilter+":"+gid+":"+database.maxRowId()+":"+reviews+":"+editSelection.size()+":"+Arrays.toString(gst);if(!force&&sig.equals(galleryListSignature))return;galleryListSignature=sig;galleryQueue.removeAllViews();String sql="SELECT j.id,j.name,j.edited,j.original,j.state,COALESCE(j.error,''),j.score,COALESCE(f.state,'pending') FROM jobs j LEFT JOIN fotto_uploads f ON f.job_id=j.id AND f.gallery_id=? ORDER BY j.rowid DESC LIMIT 80";int shown=0;try(Cursor c=database.getReadableDatabase().rawQuery(sql,new String[]{gid})){while(c.moveToNext()){String id=c.getString(0),name=c.getString(1),edited=c.getString(2),original=c.getString(3),state=c.getString(4),reason=c.getString(5),upload=c.getString(7);int score=c.getInt(6);if(!matchesFilter(state,upload))continue;addGalleryRow(id,name,edited,original,state,reason,score,upload);shown++;if(shown>=36)break;}}if(shown==0){gap(galleryQueue,16);label(galleryQueue,"Nenhuma foto neste filtro.",13);}updateEditSelectionLabel();}
 boolean matchesFilter(String state,String upload){if("approved".equals(galleryFilter))return "done".equals(state);if("review".equals(galleryFilter))return "review".equals(state);if("sent".equals(galleryFilter))return "done".equals(state)&&"done".equals(upload);if("pending".equals(galleryFilter))return !"review".equals(state)&&(!"done".equals(state)||!"done".equals(upload));return true;}
 void addGalleryRow(String id,String name,String edited,String original,String state,String reason,int score,String upload){LinearLayout box=row();box.setPadding(dp(9),dp(9),dp(9),dp(9));int bg="review".equals(state)?0xfffffbf5:"error".equals(state)?0xfffff5f5:CARD;box.setBackground(border(bg,15));galleryQueue.addView(box,new LinearLayout.LayoutParams(-1,-2));ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);thumb.setBackground(shape(0xffedf1f6,11));box.addView(thumb,new LinearLayout.LayoutParams(dp(76),dp(76)));String raw=(edited!=null&&!edited.isEmpty())?edited:original;if(raw!=null&&!raw.isEmpty()){Bitmap cached=thumbCache.get(raw);if(cached!=null)thumb.setImageBitmap(cached);else thumbnails.execute(()->{Bitmap b=decodeImage(raw,160);handler.post(()->{if(!destroyed&&b!=null){thumbCache.put(raw,b);thumb.setImageBitmap(b);}});});}
  LinearLayout info=vertical();info.setPadding(dp(10),0,dp(5),0);box.addView(info,new LinearLayout.LayoutParams(0,-2,1));info.addView(text(displayName(name,state),12,TEXT,true));gap(info,3);LinearLayout chips=row();TextView st=chip(statusLabel(state,upload),statusColor(state,upload));chips.addView(st);if(score>0){TextView sc=chip(score+"/10",scoreColor(score));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,dp(28));cp.leftMargin=dp(5);chips.addView(sc,cp);}info.addView(chips);if("review".equals(state)&&reason!=null&&!reason.isEmpty()){gap(info,4);TextView why=text(reason,10,MUTED,false);why.setMaxLines(2);info.addView(why);}LinearLayout acts=row();CheckBox mark=new CheckBox(this);mark.setChecked(editSelection.contains(id));mark.setContentDescription("Selecionar "+name);mark.setOnCheckedChangeListener((b,checked)->{if(checked)editSelection.add(id);else editSelection.remove(id);updateEditSelectionLabel();});acts.addView(mark,new LinearLayout.LayoutParams(dp(42),dp(42)));Button edit=miniButton("Editar",v->openEditor(id,editSelection.isEmpty()?Collections.singletonList(id):new ArrayList<>(editSelection)));acts.addView(edit,new LinearLayout.LayoutParams(0,dp(40),1));if("review".equals(state)){Button approve=miniButton("Aprovar",v->approveReview(id,name,edited));approve.setTextColor(WARNING);acts.addView(approve,new LinearLayout.LayoutParams(0,dp(40),1));}info.addView(acts);if(raw!=null&&!raw.isEmpty())thumb.setOnClickListener(v->openImage(raw));gap(galleryQueue,7);}
 TextView chip(String s,int color){TextView t=text(s,9,color,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(8),0,dp(8),0);t.setBackground(shape(color==WARNING?0xfffff2dd:color==SUCCESS?0xffe8f7ef:color==ERROR?0xffffeded:0xffeaf4ff,14));return t;}int scoreColor(int score){return score>=8?SUCCESS:score>=5?WARNING:ERROR;}String displayName(String name,String state){if(name==null)return "Foto";return name.replaceFirst("(?i)\\.jpg$","review".equals(state)?"_REVISAO.jpg":"_Editada.jpg");}
 String statusLabel(String state,String upload){if("review".equals(state))return "REVISÃO";if("error".equals(state)||"originalError".equals(state))return "FALHA";if("editing".equals(state)||"ready".equals(state)||"original".equals(state))return "PROCESSANDO";if("done".equals(state)){if("done".equals(upload))return "ENVIADA";if("uploading".equals(upload))return "ENVIANDO";if("error".equals(upload))return "FALHA ENVIO";return "APROVADA";}return state.toUpperCase(Locale.ROOT);}int statusColor(String state,String upload){String l=statusLabel(state,upload);return l.contains("FALHA")?ERROR:l.equals("REVISÃO")?WARNING:l.equals("ENVIADA")?SUCCESS:BLUE;}

